INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1032501043, 11, 0, "", 0, 1032501, 1, "それにしてもすばらしいケーキですわね。\nどちらの高名な菓子職人に\n依頼されたのでしょう？", 103211, 6, 1);
