INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1034501040, 11, 0, "", 0, 1034501, 1, "わあ……素敵なケーキね！\nえ？　キミが作ったの？\nすごいじゃない！", 103411, 4, 1);
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1034501041, 91, "", "", "", 1034501, "", "", 0, "", "");
