INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1034501046, 11, 0, "", 0, 1034501, 1, "なんでって、それは……\nキミがお祝いに来てくれるかも、\nなんて思ってたから……", 103411, 5, 1);
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1034501047, 91, "", "", "", 1034501, "", "", 0, "", "");
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1034501048, 21, "", "", "", 1034501, 0, "vo_adv_1034501_003", "vo_adv_1034501", 0, "");
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1034501049, 11, 0, "", 0, 1034501, 1, "だから、今日は麦しゅわは封印よ。\n麦しゅわもありの大人な誕生日は、\nキミが大人になってから……ね？", 103411, 5, 1);
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1034501050, 91, "", "", "", 1034501, "", "", 0, "", "");
