INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1052501040, 11, 0, "", 0, 1052501, 1, "素敵なケーキをありがとう！\nまさかこんな盛大に\nお祝いしてもらえるなんて\n思わなかったわ！", 105211, 6, 1);
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1052501041, 91, "", "", "", 1052501, "", "", 0, "", "");
