INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1070501039, 13, "", "", "", 1070501, "", 870, 107011, "", "");
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1070501040, 11, 0, "", 0, 1070501, 1, "ふむ、よい趣向ですね。\n敬うべき相手を忘れず、恩を忘れず、\n健勝を祝う宴を開く……\n礼節を弁えた人間は好きですよ。", 107011, 4, 1);
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1070501041, 91, "", "", "", 1070501, "", "", 0, "", "");
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1070501042, 21, "", "", "", 1070501, 0, "vo_adv_1070501_001", "vo_adv_1070501", 0, "");
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1070501043, 11, 0, "", 0, 1070501, 1, "しかし一時には\n赤子同然だった貴方が\nここまで成長したこと……\nとても喜ばしく思います。", 107011, 5, 1);
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1070501044, 91, "", "", "", 1070501, "", "", 0, "", "");
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1070501045, 21, "", "", "", 1070501, 0, "vo_adv_1070501_002", "vo_adv_1070501", 0, "");
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1070501046, 11, 0, "", 0, 1070501, 1, "ただ、そうですね……\n厚意に預かるばかり、\nというのも性に合いませんし。\n何かご褒美をあげましょう。", 107011, 5, 1);
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1070501047, 91, "", "", "", 1070501, "", "", 0, "", "");
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1070501048, 21, "", "", "", 1070501, 0, "vo_adv_1070501_003", "vo_adv_1070501", 0, "");
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1070501049, 11, 0, "", 0, 1070501, 1, "焦って決めずとも構いません。\n今日は一日、私が飽きるまで\n貴方に付き合ってもらう予定ですから。\nふふ……期待していますよ？", 107011, 5, 1);
INSERT INTO `v1_307217447322e2b01e8785199a17fd2fce7eba736a4e95ae92ceb633fb209904` VALUES (1070501050, 91, "", "", "", 1070501, "", "", 0, "", "");
